package com.company.platform.commerce.infrastructure.persistence;
import com.company.platform.commerce.domain.product.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository; import java.sql.Timestamp; import java.util.*;
@Repository public class JdbcSellableProductRepository implements SellableProductRepository { private final JdbcTemplate jdbc; public JdbcSellableProductRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public SellableProduct save(SellableProduct p){jdbc.update("INSERT INTO sellable_products(id,tenant_id,marketplace_product_id,store_id,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET status=?,updated_at=?",p.id(),p.tenantId(),p.marketplaceProductId(),p.storeId(),p.status().name(),Timestamp.from(p.createdAt()),Timestamp.from(p.updatedAt()),p.status().name(),Timestamp.from(p.updatedAt()));return p;}
 private SellableProduct map(java.sql.ResultSet r,int n)throws java.sql.SQLException{return SellableProduct.rehydrate((UUID)r.getObject("id"),(UUID)r.getObject("tenant_id"),(UUID)r.getObject("marketplace_product_id"),(UUID)r.getObject("store_id"),SellableProductStatus.valueOf(r.getString("status")),r.getTimestamp("created_at").toInstant(),r.getTimestamp("updated_at").toInstant());}
 public Optional<SellableProduct> findByTenantIdAndId(UUID t,UUID id){return jdbc.query("SELECT * FROM sellable_products WHERE tenant_id=? AND id=?",this::map,t,id).stream().findFirst();} public List<SellableProduct> findAllByTenantId(UUID t){return jdbc.query("SELECT * FROM sellable_products WHERE tenant_id=? ORDER BY created_at",this::map,t);}
}
